import { Loader, Button, Card } from "march/ui"

// çaydanlık: "Demle" yükleyiciyi kendi işaretiyle (☕) gösterir; metin geri sayar, bitince çay hazır
export function KettleLoader() {
  let $left = 0
  const brew = () => {
    $left = 3
    const t = setInterval(() => { $left--; if ($left <= 0) clearInterval(t) }, 700)
  }
  return <Card title="Çay ocağı">
    {() => $left > 0
      ? <Loader spinner={<span sx={{ text: "2xl" }}>☕</span> as Node} fade={false} text={() => `Demleniyor… ${$left}`} />
      : <div sx={{ flex: ["row", "center"], gap: 2 }}><span>Çay hazır 🫖</span><Button size="sm" on:click={brew}>Demle</Button></div>}
  </Card>
}

import { Loader, Button, Card } from "march/ui"

// bir satış panosu yenilenirken: içerik yerinde kalır, üstüne perde (overlay) iner; veri gelince kalkar
export function DashboardOverlay() {
  let $busy = false
  let $orders = 1284
  const refresh = () => { $busy = true; setTimeout(() => { $orders += Math.floor(Math.random() * 40); $busy = false }, 1200) }
  return <Card title="Satış panosu" sx={{ p: 3 }}>
    <div style={{ position: "relative", "min-height": "6rem" }}>
      <p sx={{ text: ["xl", "bold"] }}>{() => `${$orders.toLocaleString("tr-TR")} sipariş`}</p>
      <p sx={{ color: "muted" }}>Bu çeyrekte ortalama sepet 412 ₺.</p>
      {() => $busy ? <Loader overlay color="brand-orange" text="Veriler yenileniyor…" /> : null}
    </div>
    <Button size="sm" disabled={() => $busy} on:click={refresh}>Yenile</Button>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { LoaderLab } from "./LoaderLab.tsx"

// LoaderLab'in testleri: kaydedince Testler sekmesinde çalışır
test("yükleyici role=status, metin görünür", () => {
  const s = renderTest(() => <LoaderLab />)
  const l = s.get(".lab-text")
  expect(l?.getAttribute("role")).toBe("status")
  expect(l?.querySelector(".m-loader-text")?.textContent).toBe("Panolar hazırlanıyor…")
})

test("text yoksa label yalnız ekran okuyucuya; fade={false} hemen görünür", () => {
  const s = renderTest(() => <LoaderLab />)
  const l = s.get(".lab-label")
  expect(l?.querySelector(".m-sr-only")?.textContent).toBe("Kullanıcılar açılıyor")
  expect(l?.classList.contains("is-still")).toBe(true)
})

test("spinner={false} halkayı kaldırır, overlay perde olur", async () => {
  const s = renderTest(() => <LoaderLab />)
  await s.flush()
  expect(s.get(".lab-bare")?.querySelector(".m-loading")).toBe(null)
  expect(s.get(".lab-text")?.querySelector(".m-loading")).not.toBe(null)
  expect(s.get(".lab-overlay")?.classList.contains("m-loader-overlay")).toBe(true)
})

test("text erişimcisi düğmeyle güncellenir", async () => {
  const s = renderTest(() => <LoaderLab />)
  await s.click("İlerlet")
  expect(s.get(".lab-pct .m-loader-text")?.textContent).toBe("%40 tamam")
})
